    lines = input_str.strip().split('\n')
    lines = [line.strip() for line in lines if line]

    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    skip_empty = True

    results = []

    for _ in range(t):
        while skip_empty and idx < len(lines):
            if lines[idx]:
                skip_empty = False
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        tree = []
        for i in range(n):
            parts = lines[idx].split()
            idx += 1
            if parts[0] == '-1':
                l, r = int(parts[1]), int(parts[2])
                tree.append(('int', l, r))
            else:
                tree.append(('leaf', int(parts[0])))

        # Use DP memoization
        # For node u, compute the value assuming it's the root of a subgame
        # The key insight: each internal node subtree is independent in terms of game outcome
        # For a subtree with k leaves, exactly k-1 reductions happen within that subtree
        # Players alternate turns; Pieguy starts globally but within a subtree it's about turn parity

        memo = {}

        def compute(u):
            if u == -1:
                return 0, 0  # Invalid sentinel

            state = tree[u]
            if (u,) in memo:
                return memo[(u,)]

            case_val, turns = memo.get((u,), (0, 0))

            if state[0] == 'leaf':
                # Single leaf node
                value = state[1]
                memo[(u,)] = (value, 0)
                return value

            left, right = state[1], state[2]
            left_val, left_turns = compute(left)  # Value and number of moves within left subtree
            right_val, right_turns = compute(right)  # ...

            # Total moves in this subtree = left_turns + right_turns
            total_turns = left_turns + right_turns

            # If moves are even, Pieguy makes the last move (may prefer if maximizes)
            # If odd, Piegirl makes the last move (may prefer if minimizes)

            # Pieguy maximizes, Piegirl minimizes
            # The final value will be max(left_val, right_val) if Pieguy chooses,
            # min(left_val, right_val) if Piegirl chooses

            if total_turns % 2 == 1:
                # Piegirl makes last move -> minimizes
                final_value = min(left_val, right_val)
            else:
                # Pieguy makes last move -> maximizes
                final_value = max(left_val, right_val)

            memo[(u,)] = (final_value, total_turns)
            return final_value

        # Note: the tree is always rooted at node 0
        # The game is played optimally, players alternate globally
        # Within each subtree, the move count determines who makes the final decision

        final_value = compute(0)

        # Back to function-level return, in a real CP solution this would be printed
        results.append(str(final_value))

    return '\n'.join(results)


