def solve_tc(n, m, edges):
    if m == 0:
        return pow(2, n - 2, MOD)

    # Union-Find to track love relationships
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    edge_color = {}  # Store known relationship types

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return
        if rank[a] < rank[b]:
            a, b = b, a
        parent[b] = a
        if rank[a] == rank[b]:
            rank[a] += 1

    # Build components based on love relationships
    for a, b, c in edges:
        if c == 1:
            union(a, b)
        edge_color[(a, b)] = 1 if c == 1 else 0

    # Count validated configurations
    roots = set(find(i) for i in range(1, n + 1))
    components = {r: [] for r in roots}

    for i in range(1, n + 1):
        components[find(i)].append(i)

    # Verify constraints and count
    for s in components:
        sz = len(components[s])
        if sz == 1:
            return pow(2, n - 2, MOD)

    return pow(2, n - 2 - m, MOD)

