    x = [0.0] * n
    visited = [False] * n
    valid = True

    for i in range(n):
        if not visited[i]:
            # Visit this component starting from node i with value 0.0
            stack = [(i, 0.0)]
            visited[i] = True
            x[i] = 0.0

            while stack:
                u, val_u = stack.pop()
                for v, c in adj[u]:
                    # Edge constraint: x[u] + x[v] = c => x[v] = c - x[u]
                    expected_v = c - val_u
                    if not visited[v]:
                        visited[v] = True
                        x[v] = expected_v
                        stack.append((v, x[v]))
                    elif abs(x[v] - expected_v) > 1e-9:
                        # Inconsistent constraint found
                        valid = False
                        break
                if not valid:
                    break

    if not valid:
        return "NO"

    # Output results
