import os

def is_geometric(sequence):
    """Check if a sequence is a geometric progression"""
    n = len(sequence)

    # 1 or 2 elements are always valid GPs
    if n <= 2:
        return True

    # All zeros is a valid GP
    if all(x == 0 for x in sequence):
        return True

    # If first element is 0, remaining must all be 0
    if sequence[0] == 0:
        if sequence[1] == 0:
            return all(x == 0 for x in sequence[2:])
        else:
            return False

    # Calculate ratio and verify
    ratio = float(sequence[1]) / sequence[0]

    for i in range(2, n):
        expected = sequence[i-1] * ratio
        # Use tolerance for floating point comparison
        if abs(float(sequence[i]) - expected) > 1e-7:
            return False

    return True

