def solution(input_str):
    import sys
    sys.setrecursionlimit(500000)

    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"
    n, m = map(int, lines[0].split())

    num_nodes = 2 * m
    graph = [[] for _ in range(num_nodes)]

    def lit_to_node(lit):
        return 2 * (abs(lit) - 1) + (0 if lit > 0 else 1)

    # Build implication graph: for each clause (l1 U l2 U ... U lk)
    # Add edges ¬li → lj and ¬lj → li
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        literals = parts[1:]

        def lit_to_neg(u):
            return u ^ 1

        # For all pairs, add edges between their negations
        for idx in range(len(literals)):
            for jdx in range(len(literals)):
                if idx == jdx:
                    continue
                u = lit_to_node(literals[idx])
                v = lit_to_node(literals[jdx])
                graph[lit_to_neg(u)].append(v)

    # Tarjan's SCC algorithm
    vis = [False] * num_nodes
    comp = [-1] * num_nodes
    id_ = [0] * num_nodes
    stack = []
    on_stack = [False] * num_nodes
    dfn = [0] * num_nodes
    low = [0] * num_nodes
    timer = 0
    scc_cnt = 0

    def dfs(u):
        nonlocal timer, scc_cnt
        vis[u] = True
        on_stack[u] = True
        stack.append(u)
        dfn[u] = low[u] = timer
        timer += 1

        for v in graph[u]:
            if not vis[v]:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], dfn[v])

        if low[u] == dfn[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                comp[w] = scc_cnt
                id_[w] = scc_cnt
                if u == w:
                    break
            scc_cnt += 1

    for i in range(num_nodes):
        if not vis[i]:
            dfs(i)

    # Check satisfiability
    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "NO\n"

    # Construct assignment
    ans = []
    for i in range(m):
        x = comp[2 * i + 1]
        nx = comp[2 * i]
        if x < nx:
            ans.append("1")
        else:
            ans.append("0")

    return "YES\n" + "".join(ans) + "\n"

