    """
    Solution to the microwave banana problem.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    ops = []
    for i in range(1, n + 1):
        line = lines[i]
        parts = list(map(int, line.split()))
        # x_i = x'_i / 10^5
        ops.append((parts[0], parts[1] / 10**5, parts[2]))

    # ans[j] = earliest time step to obtain exactly j bananas
    ans = [-1] * (m + 1)

    # Initially we have 0 bananas (reachable at time 0)
    reachable = {0}

    # Process each time step
    for time, (t, x, y) in enumerate(ops, 1):
        new_reachable_at_this_step = set()

        for base in reachable:
            # Apply operation a times where 1 <= a <= y
            current = base
            for a in range(1, y + 1):
                if t == 1:
                    # Type 1: addition
                    current = math.ceil(current + x)
                else:
                    # Type 2: multiplication  
                    current = math.ceil(current * x)

                # Cap at m+1 to avoid unbounded growth
                if current > m:
                    break

                val = int(current)
                if ans[val] == -1:
                    ans[val] = time
                new_reachable_at_this_step.add(val)

        # All values from previous step remain reachable
        # Plus all new values from this step
        reachable.update(new_reachable_at_this_step)

    # Return answer for j = 1 to m
    return ' '.join(map(str, ans[1:m+1])) + '\n'

