    # Check if any pairing is stable
    # Use brute force for small N, or a stable matching algorithm

    def is_stable(matching):
        """
        Check if a matching is stable.
        matching[i] = j means city i is paired with city j
        """
        for i in range(n):
            for j in range(i + 1, n):
                if matching[i] != j:
                    # Check if both prefer each other over their partners
                    u_prefers = costs[i][j] < costs[i][matching[i]]
                    v_prefers = costs[j][i] < costs[j][matching[j]]
                    if u_prefers and v_prefers:
                        return False
        return True

    # Try stable roommates matching
    # For N cities, we need to pair them all up

    def stable_roommates(match_costs):
        n = len(match_costs)

        # Simple greedy approach - pair with cheapest available
        matched = [-1] * n
        free = list(range(n))

        while len(free) >= 2:
            i = free.pop(0)
            best_j = -1
            best_cost = float('inf')

            for j in free:
                cost_to_j = match_costs[i][j]
                cost_to_i = match_costs[j][i]
                combined = cost_to_j + cost_to_i

                if combined < best_cost:
                    best_cost = combined
                    best_j = j

            if best_j != -1 and best_j != i:
                matched[i] = best_j
                matched[best_j] = i
            else:
                free.append(i)

        return matched

