    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and 
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    def same_side(p1, p2, a, b):
        """Check if p1 and p2 are on same side of line ab"""
        return cross(a, b, p1) * cross(a, b, p2) > 0

    def diagonal_valid(i, j, pts, n):
        """Check if diagonal (i,j) is inside polygon"""
        for k in range(n):
            p1 = pts[k]
            p2 = pts[(k + 1) % n]
            # Skip edges touching i or j
            if p1 == pts[i] or p1 == pts[j] or p2 == pts[i] or p2 == pts[j]:
                if (not on_segment(p1, pts[i], pts[j]) and 
                    not on_segment(p2, pts[i], pts[j])):
                    c1 = cross(pts[i], pts[j], p1)
                    c2 = cross(pts[i], pts[j], p2)
                    if c1 == 0 or c2 == 0:
                        if same_side(p1, p2, pts[i], pts[j]):
                            return False
                        continue
                    # Intersection check
                    dx1 = pts[j][0] - pts[i][0]
                    dy1 = pts[j][1] - pts[i][1]

                    dx2 = p2[0] - p1[0]
                    dy2 = p2[1] - p1[1]

                    det = dx1 * dy2 - dx2 * dy1
                    if det == 0:
                        continue

                    t1 = dx2 * (pts[i][1] - p1[1]) - dy2 * (pts[i][0] - p1[0])
                    t2 = dx1 * (pts[i][1] - p2[1]) - dy1 * (pts[i][0] - p2[0])

                    t = dx1 * t1 - dy1 * t2
                    if det == 0:
                        continue

                    if 0 <= t <= det and 0 <= t1 <= det and 0 <= t2 <= det:
                        return False

        return True

    # Count triangulations with standard DP
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][(i + 1) % n] = 1

    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):
                dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    return str(dp[0][n-1]) + '\n'

