import sys

MOD = 1051131

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def power(base, exp):
    result = 1
    base %= MOD
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp //= 2
    return result

def build_transition_matrix(n):
    """Build n x n transition matrix for islands 1 to n."""
    M = [[0] * n for _ in range(n)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                M[i-1][j-1] = 1  # Stay at same island
            else:
                bridges = power(2, gcd(i, j))
                M[i-1][j-1] = bridges
    return M

def matrix_multiply(A, B, n):
    """Multiply two n x n matrices modulo MOD."""
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_power(M, t, n):
    """Compute M^t using binary exponentiation."""
    n = len(M)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in M]
    while t > 0:
        if t % 2 == 1:
            result = matrix_multiply(result, base, n)
        base = matrix_multiply(base, base, n)
        t //= 2
    return result

