            wires.append((x, y))

            if x in touch_counts:
                touch_counts[x] += 1
            else:
                touch_counts[x] = 1
            if y in touch_counts:
                touch_counts[y] += 1
            else:
                touch_counts[y] = 1

        if n == 1:
            output_lines.append('0')
            continue

        # Find contact point with maximum frequency
        most_freq_point = max(touch_counts, key=touch_counts.get)

        ops = 0
        operations = []

        for i, (x, y) in enumerate(wires):
            if x == most_freq_point or y == most_freq_point:
                pass  # Already connected
            else:
                # This wire doesn't connect to most_freq_point
                # Change one endpoint to connect to most_freq_point
                # Prefer changing the endpoint that's not touching the most frequent point
                if x < y:
                    # Change second endpoint
                    operations.append((i + 1, y, most_freq_point))
                else:
                    # Change first endpoint
                    operations.append((i + 1, x, most_freq_point))
                ops += 1

        output_lines.append(str(ops))
        for w, a, b in operations:
            output_lines.append(f'{w} {a} {b}')

    return '\n'.join(output_lines)


