def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    p_pos = {val: i for i, val in enumerate(p)}
    parent = list(range(n))

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Build connected components - elements with complements must be in same set
    for i in range(n):
        x = p[i]
        if (a - x) in p_pos:
            union(i, p_pos[a - x])
        if (b - x) in p_pos:
            union(i, p_pos[b - x])

    # Group by component
    group_members = {}
    for i in range(n):
        r = find(i)
        if r not in group_members:
            group_members[r] = []
        group_members[r].append(i)

    result = [0] * n
    possible = True

    for members in group_members.values():
        # Check if all elements in this component can go to set A
        can_A = all((a - p[i]) in p_pos for i in members)
        # Check if all elements can go to set B
        can_B = all((b - p[i]) in p_pos for i in members)

        if not can_A and not can_B:
            possible = False
            break
        elif can_A:
            for i in members:
                result[i] = 0
        else:
            for i in members:
                result[i] = 1

    if not possible:
        return "NO\n"

    # Final verification
    for i in range(n):
        x = p[i]
        if result[i] == 0:
            if (a - x) in p_pos:
                j = p_pos[a - x]
                if result[j] != 0:
                    return "NO\n"
        else:
            if (b - x) in p_pos:
                j = p_pos[b - x]
                if result[j] != 1:
                    return "NO\n"

    return "YES\n" + " ".join(map(str, result)) + "\n"

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, b = map(int, lines[0].split())

    items = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        c = parts[0]
        d = parts[1]
        x = parts[2] if len(parts) > 2 else 1
        items.append((c, d, x - 1))

    # Build adjacency list for tree (parent -> children)
    children = [[] for _ in range(n)]
    for i in range(n):
        parent = items[i][2]
        if parent >= 0:
            children[parent].append(i)

    from collections import defaultdict
    INF = float('inf')

    # dp[u][k] = minimum cost to buy k items in subtree rooted at u
    # Process bottom-up using reverse index order (ensured by problem constraint x_i < i)
    dp = [defaultdict(lambda: INF) for _ in range(n)]

    for i in range(n - 1, -1, -1):
        c, d, _ = items[i]

        # Initialize with base case for leaf: 0 items -> 0 cost
        if len(dp[i]) == 0:
            dp[i] = {0: 0}

        # Process leaf node - can buy item without coupon
        if c <= INF:
            new_dp = {k: v for k, v in dp[i].items()}
            new_dp[1] = min(new_dp.get(1, INF), c)
            dp[i] = new_dp

        # Process children
        if i > 0:  # Skip root (item 1 which has no dependency)
            parent_state_1 = dp[parent][1]
            parent_state_2 = dp[parent][2]

            for child in reversed(children[i]):
                # Merge child states
                child = children[i]
                # Merge children using knapsack-like approach
                merged = defaultdict(lambda: INF)
                for k1, cost1 in dp[i].items():
                    for k2, cost2 in child.items():
                        new_k = k1 + k2
                        if new_k <= n:
                            merged[new_k] = min(merged[new_k], cost1 + cost2)
                dp[i] = merged

    # Find maximum items within budget
    result = [0]
    for k, cost in dp[0].items():
        if cost <= b:
            result.append(k)

    return max(result) if result else 0

import math
import sys

class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def update(self, i, delta):
        i += 1  # 0-indexed to 1-indexed
        while i <= len(self.tree) - 1:
            self.tree[i] += delta
            i += i & (-i)

    def query(self, i):
        i += 1
        result = 0
        while i > 0:
            result += self.tree[i]
            i -= i & (-i)
        return result

    def range_query(self, l, r):
        if l > r:
            return 0
        return self.query(r) - self.query(l - 1)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, q = map(int, lines[0].split())

    perm = list(range(1, n + 1))
    total_inversions = 0

    block_size = int(math.sqrt(n)) + 1
    num_blocks = (n + block_size - 1) // block_size

    block_fenwick = [FenwickTree(n) for _ in range(num_blocks)]

    for i in range(n):
        b_idx = i // block_size
        val = perm[i]
        block_fenwick[b_idx].update(val, 1)

    output_lines = []

    for i in range(1, q + 1):
        l, r = map(int, lines[i].split())
        l_idx, r_idx = l - 1, r - 1

        if l_idx > r_idx:
            l_idx, r_idx = r_idx, l_idx

        if l_idx == r_idx:
            output_lines.append(str(total_inversions))
            continue

        x = perm[l_idx]
        y = perm[r_idx]

        if x == y:
            output_lines.append(str(total_inversions))
            continue

        target_min = min(x, y)
        target_max = max(x, y)

        # Count elements between l_idx and r_idx with values in (target_min, target_max)
        count_between = 0

        l_block = l_idx // block_size
        r_block = r_idx // block_size

        if l_block == r_block:
            for k in range(l_idx + 1, r_idx):
                if target_min < perm[k] < target_max:
                    count_between += 1
        else:
            # Partial block for l
            left_end = (l_block + 1) * block_size - 1
            for k in range(l_idx + 1, left_end + 1):
                if target_min < perm[k] < target_max:
                    count_between += 1

            # Full blocks
            for b_idx in range(l_block + 1, r_block):
                left_val = target_min + 1
                right_val = target_max - 1
                cnt = block_fenwick[b_idx].range_query(left_val, right_val)
                count_between += cnt

            # Partial block for r
            right_start = r_block * block_size
            for k in range(right_start, r_idx):
                if target_min < perm[k] < target_max:
                    count_between += 1

        if x < y:
            change = 1 + 2 * count_between
        else:
            change = -1 - 2 * count_between

        total_inversions += change

        # Swap
        perm[l_idx], perm[r_idx] = perm[r_idx], perm[l_idx]

        # Update Fenwick trees
        b1 = l_idx // block_size
        b2 = r_idx // block_size

        if b1 == b2:
            block_fenwick[b1].update(x, -1)
            block_fenwick[b1].update(y, 1)
            block_fenwick[b1].update(y, -1)
            block_fenwick[b1].update(x, 1)
        else:
            block_fenwick[b1].update(x, -1)
            block_fenwick[b1].update(y, 1)
            block_fenwick[b2].update(y, -1)
            block_fenwick[b2].update(x, 1)

        output_lines.append(str(total_inversions))

    return '\n'.join(output_lines)

