def solution(input_str):
    # Parse the input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for line in lines[1:]:
        parts = line.strip().split()
        s = list(map(int, list(parts[0])))
        c = int(parts[1])
        attempts.append((s, c))

    # For small n, we can use direct brute force with pruning
    # For larger n, use meet-in-the-middle approach

    if n <= 25:
        # Brute force approach
        count = 0
        for mask in range(1 << n):
            valid = True
            for j in range(m):
                cnt = 0
                for k in range(n):
                    if ((mask >> k) & 1) == attempts[j][0][k]:
                        cnt += 1
                if cnt != attempts[j][1]:
                    valid = False
                    break
            if valid:
                count += 1
        return str(count)
    else:
        # Meet-in-the-middle approach for n > 25
        half1_len = n // 2
        half2_len = n - half1_len

        half1_contribs = []
        for mask in range(1 << half1_len):
            contrib = []
            for j in range(m):
                cnt = 0
                for k in range(half1_len):
                    if ((mask >> k) & 1) == attempts[j][0][k]:
                        cnt += 1
                contrib.append(cnt)
            half1_contribs.append(tuple(contrib))

        half2_contribs = []
        for mask in range(1 << half2_len):
            contrib = []
            for j in range(m):
                cnt = 0
                for k in range(half2_len):
                    if ((mask >> k) & 1) == attempts[j][0][half1_len + k]:
                        cnt += 1
                contrib.append(cnt)
            half2_contribs.append(tuple(contrib))

        count = 0
        for c1 in half1_contribs:
            for c2 in half2_contribs:
                if all(c1[j] + c2[j] == attempts[j][1] for j in range(m)):
                    count += 1
        return str(count)
